{
  "predictors": [
    {
      "name": "Internet Presence",
      "construction": "Measure the number of mentions of the company on internet search engines over the past month.",
      "rationale": "Companies with a higher internet presence may be more likely to attract investor attention and demand, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Employee Satisfaction",
      "construction": "Use data from job review websites to calculate an average employee satisfaction score for each company.",
      "rationale": "Companies with satisfied employees may have higher productivity and better performance, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Patent Activity",
      "construction": "Count the number of patents filed by the company in the past year.",
      "rationale": "Companies with more patent activity may be more innovative, leading to higher future growth and stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Product Diversity",
      "construction": "Calculate the number of distinct product categories the company operates in.",
      "rationale": "Companies with a diverse product portfolio may be more resilient to industry-specific shocks, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Customer Loyalty",
      "construction": "Use customer survey data to calculate a customer loyalty score for each company.",
      "rationale": "Companies with loyal customers may have more stable future revenues, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Environmental Impact",
      "construction": "Calculate a score based on the company's carbon emissions, waste production, and other environmental factors.",
      "rationale": "Companies with a lower environmental impact may be more attractive to socially conscious investors, leading to higher stock returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Executive Age",
      "construction": "Calculate the average age of the company's executive team.",
      "rationale": "Companies with younger executives may be more innovative and adaptable, leading to higher stock returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Supplier Diversity",
      "construction": "Calculate a score based on the diversity of the company's suppliers in terms of geography and industry.",
      "rationale": "Companies with a diverse supplier base may be more resilient to supply chain disruptions, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Cybersecurity Investment",
      "construction": "Estimate the company's investment in cybersecurity based on its IT spending and other factors.",
      "rationale": "Companies with strong cybersecurity may be less likely to suffer damaging data breaches, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Brand Strength",
      "construction": "Calculate a score based on the company's brand recognition and reputation, using survey data and media mentions.",
      "rationale": "Companies with strong brands may be able to charge higher prices and earn higher profits, leading to higher stock returns.",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
